'use strict';

const fs = require('fs');
const path = require('path');

const PATCH_MARKER = 'withArivuBlog';

function normalizePathPrefix(prefix) {
  let value = String(prefix || '/blog/').trim();
  if (!value.startsWith('/')) value = `/${value}`;
  if (!value.endsWith('/')) value = `${value}/`;
  return value;
}

function buildArivuBlogConfigContent(pathPrefix) {
  const normalized = normalizePathPrefix(pathPrefix);
  const base = normalized.replace(/\/$/, '') || '/blog';
  return `/**
 * Arivu blog — auto-generated by arivu-blog-install
 * Merges static /blog rewrites into your Next.js config.
 */
export function getArivuBlogRewrites() {
  return [
    { source: '${base}', destination: '${base}/index.html' },
    { source: '${base}/', destination: '${base}/index.html' },
    { source: '${base}/:path+/', destination: '${base}/:path+/index.html' },
    { source: '${base}/:path+', destination: '${base}/:path+/index.html' },
  ];
}

export function withArivuBlog(config = {}) {
  const existingRewrites = config.rewrites;
  return {
    ...config,
    async rewrites() {
      const arivu = getArivuBlogRewrites();
      const base = typeof existingRewrites === 'function'
        ? await existingRewrites()
        : (existingRewrites || []);
      return [...arivu, ...base];
    },
  };
}
`;
}

function buildArivuBlogConfigCjs(pathPrefix) {
  const normalized = normalizePathPrefix(pathPrefix);
  const base = normalized.replace(/\/$/, '') || '/blog';
  return `/**
 * Arivu blog — auto-generated by arivu-blog-install
 */
function getArivuBlogRewrites() {
  return [
    { source: '${base}', destination: '${base}/index.html' },
    { source: '${base}/', destination: '${base}/index.html' },
    { source: '${base}/:path+/', destination: '${base}/:path+/index.html' },
    { source: '${base}/:path+', destination: '${base}/:path+/index.html' },
  ];
}

function withArivuBlog(config = {}) {
  const existingRewrites = config.rewrites;
  return {
    ...config,
    async rewrites() {
      const arivu = getArivuBlogRewrites();
      const base = typeof existingRewrites === 'function'
        ? await existingRewrites()
        : (existingRewrites || []);
      return [...arivu, ...base];
    },
  };
}

module.exports = { getArivuBlogRewrites, withArivuBlog };
`;
}

function patchPackageJson(packageJsonPath, options = {}) {
  const integrationMode = options.integrationMode || 'hybrid';
  const pkg = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));
  pkg.scripts = pkg.scripts || {};

  if (integrationMode === 'standalone-html' || integrationMode === 'hybrid' || integrationMode === 'layout') {
    if (!pkg.scripts['sync:blog']) {
      pkg.scripts['sync:blog'] = 'node scripts/sync-blog-static.mjs';
    }

    if (integrationMode !== 'layout') {
      const syncCommand = 'npm run sync:blog';
      const existingPrebuild = String(pkg.scripts.prebuild || '').trim();
      if (!existingPrebuild) {
        pkg.scripts.prebuild = syncCommand;
      } else if (!existingPrebuild.includes('sync:blog')) {
        pkg.scripts.prebuild = `${syncCommand} && ${existingPrebuild}`;
      }
    }
  }

  fs.writeFileSync(packageJsonPath, `${JSON.stringify(pkg, null, 2)}\n`);
  return pkg.scripts;
}

function patchNextConfig(configPath) {
  if (!configPath || !fs.existsSync(configPath)) {
    return { created: false, patched: false, skipped: true };
  }

  const original = fs.readFileSync(configPath, 'utf8');
  if (original.includes(PATCH_MARKER)) {
    return { created: false, patched: false, skipped: true };
  }

  const ext = path.extname(configPath);
  const isCjs = ext === '.js' && !original.includes('export ');
  const importLine = isCjs
    ? "const { withArivuBlog } = require('./arivu-blog.config.cjs');\n"
    : "import { withArivuBlog } from './arivu-blog.config.mjs';\n";

  let patched = original;

  if (/export\s+default\s+[A-Za-z_$][\w$]*\s*;?/.test(patched)) {
    patched = patched.replace(
      /export\s+default\s+([A-Za-z_$][\w$]*)\s*;?/,
      'export default withArivuBlog($1);',
    );
  } else if (/export\s+default\s+\(/.test(patched)) {
    patched = patched.replace(/export\s+default\s+/, 'export default withArivuBlog(');
    patched = `${patched.trimEnd()});\n`;
  } else if (/export\s+default\s+\{/.test(patched)) {
    patched = patched.replace(/export\s+default\s+\{/, 'export default withArivuBlog({');
    patched = patched.replace(/\}\s*;?\s*$/, '});\n');
  } else if (/module\.exports\s*=\s*[A-Za-z_$][\w$]*\s*;?/.test(patched)) {
    patched = patched.replace(
      /module\.exports\s*=\s*([A-Za-z_$][\w$]*)\s*;?/,
      'module.exports = withArivuBlog($1);',
    );
  } else if (/module\.exports\s*=\s*\{/.test(patched)) {
    patched = patched.replace(/module\.exports\s*=\s*\{/, 'module.exports = withArivuBlog({');
    patched = patched.replace(/\}\s*;?\s*$/, '});\n');
  } else {
    return { created: false, patched: false, skipped: true, reason: 'unsupported next.config shape' };
  }

  fs.writeFileSync(configPath, `${importLine}${patched}`);
  return { created: false, patched: true, skipped: false, isCjs };
}

function createDefaultNextConfig(cwd, pathPrefix) {
  const configPath = path.join(cwd, 'next.config.mjs');
  if (fs.existsSync(configPath)) {
    return { created: false, path: configPath };
  }

  fs.writeFileSync(path.join(cwd, 'arivu-blog.config.mjs'), buildArivuBlogConfigContent(pathPrefix));
  const content = `import { withArivuBlog } from './arivu-blog.config.mjs';

/** @type {import('next').NextConfig} */
const nextConfig = withArivuBlog({});

export default nextConfig;
`;
  fs.writeFileSync(configPath, content);
  return { created: true, path: configPath };
}

function writeEnvFile(cwd, values, filename) {
  const integrationMode = values.integrationMode || 'hybrid';
  const resolveSyncMode = (mode) => {
    if (mode === 'standalone-html') return 'static';
    if (mode === 'layout') return 'layout';
    return 'hybrid';
  };

  const parseEnvEntries = (content) => {
    const order = [];
    const map = new Map();
    for (const rawLine of String(content || '').split(/\r?\n/)) {
      const line = rawLine.trimEnd();
      if (!line || line.trimStart().startsWith('#')) continue;
      const match = line.match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/);
      if (!match) continue;
      if (!map.has(match[1])) order.push(match[1]);
      map.set(match[1], match[2]);
    }
    return { order, values: map };
  };

  const filePath = path.join(cwd, filename);
  const existing = fs.existsSync(filePath) ? fs.readFileSync(filePath, 'utf8') : '';
  const { order, values: envValues } = parseEnvEntries(existing);
  const updates = {
    ARIVU_BLOG_ORG: values.org,
    ARIVU_API_ORIGIN: values.apiOrigin.replace(/\/$/, ''),
    BLOG_URL_PREFIX: normalizePathPrefix(values.pathPrefix),
    ARIVU_SYNC_MODE: resolveSyncMode(integrationMode),
    ARIVU_SYNC_DEST: values.dest || './public',
    SITE_ORIGIN: values.siteOrigin || '',
    ARIVU_BLOG_WEBHOOK_SECRET: '',
    VERCEL_DEPLOY_HOOK_URL: '',
  };
  const preserveEmptyKeys = new Set([
    'ARIVU_WEBHOOK_SECRET',
    'ARIVU_BLOG_WEBHOOK_SECRET',
    'VERCEL_DEPLOY_HOOK_URL',
  ]);

  for (const [key, rawValue] of Object.entries(updates)) {
    const nextValue = rawValue == null ? '' : String(rawValue);
    const current = envValues.has(key) ? String(envValues.get(key) || '') : null;
    if (
      preserveEmptyKeys.has(key)
      && nextValue === ''
      && current !== null
      && current.trim() !== ''
    ) {
      continue;
    }
    if (!envValues.has(key)) order.push(key);
    envValues.set(key, nextValue);
  }

  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, `${order.map((key) => `${key}=${envValues.get(key)}`).join('\n')}\n`);
  return filePath;
}

function writeArivuBlogConfig(cwd, pathPrefix) {
  const filePath = path.join(cwd, 'arivu-blog.config.mjs');
  fs.writeFileSync(filePath, buildArivuBlogConfigContent(pathPrefix));
  return filePath;
}

module.exports = {
  PATCH_MARKER,
  normalizePathPrefix,
  buildArivuBlogConfigContent,
  buildArivuBlogConfigCjs,
  patchPackageJson,
  patchNextConfig,
  createDefaultNextConfig,
  writeEnvFile,
  writeArivuBlogConfig,
};
